SELECT r.id, r.user_id, r.dish_id, u.nickname AS user_nickname, u.avatar AS user_avatar, r.rating, r.content, r.images AS images_json, r.sec_state AS sec_state, r.created_at, r.useful_count AS useful_count FROM review r JOIN user u ON r.user_id = u.id WHERE r.dish_id = #{dishId} AND r.is_hidden = 0 AND (r.sec_state = 'pass'
OR r.user_id = #{viewerId}
)
ORDER BY r.created_at DESC ORDER BY r.useful_count DESC, r.created_at DESC

SELECT r.id, r.user_id, r.dish_id, u.nickname AS user_nickname, u.avatar AS user_avatar, r.rating, r.content, r.images AS images_json, r.sec_state AS sec_state, r.created_at, r.useful_count AS useful_count FROM review r JOIN user u ON r.user_id = u.id JOIN dish d ON r.dish_id = d.id WHERE d.stall_id = #{stallId} AND r.is_hidden = 0 AND (r.sec_state = 'pass'
OR r.user_id = #{viewerId}
)
ORDER BY r.created_at DESC ORDER BY r.useful_count DESC, r.created_at DESC

SELECT r.id, r.user_id, r.dish_id, u.nickname AS user_nickname, u.avatar AS user_avatar, r.rating, r.content, r.images AS images_json, r.sec_state AS sec_state, r.created_at, r.useful_count AS useful_count FROM review r JOIN user u ON r.user_id = u.id JOIN dish d ON r.dish_id = d.id JOIN stall s ON d.stall_id = s.id WHERE s.canteen_id = #{canteenId} AND r.is_hidden = 0 AND (r.sec_state = 'pass'
OR r.user_id = #{viewerId}
)
ORDER BY r.created_at DESC ORDER BY r.useful_count DESC, r.created_at DESC

SELECT d.stall_id AS stallId, AVG(r.rating) AS avgRating FROM review r JOIN dish d ON r.dish_id = d.id WHERE d.stall_id IN
#{sid}
AND r.is_hidden = 0 AND r.sec_state = 'pass' GROUP BY d.stall_id

